import pyomo.environ as pyo

DATA = {
    "balloon_capacity": 4,        # visitors per hot-air balloon
    "gondola_capacity": 6,        # visitors per gondola lift
    "balloon_pollution": 10,      # pollution units per hot-air balloon
    "gondola_pollution": 15,      # pollution units per gondola lift
    "max_balloon_rides": 10,      # at most this many balloon rides
    "min_visitors": 70,           # at least this many visitors transported
    "gondola_ub": 0,              # placeholder, overridden below with a valid large-ish bound
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # 1. Sets
    model.MODES = pyo.Set(initialize=["balloon", "gondola"])

    # A safe explicit upper bound for gondola rides (derived from data, not magic)
    gondola_ub = d["min_visitors"]  # transporting all with gondolas needs at most this many

    # 2. Variables
    def balloon_bounds(m):
        return (0, d["max_balloon_rides"])

    def gondola_bounds(m):
        return (0, gondola_ub)

    def var_bounds(m, mode):
        if mode == "balloon":
            return balloon_bounds(m)
        return gondola_bounds(m)

    model.x = pyo.Var(
        model.MODES,
        within=pyo.NonNegativeIntegers,
        bounds=var_bounds,
    )

    # 3. Objective: minimize total pollution
    model.obj = pyo.Objective(
        expr=sum(
            model.x["balloon"] * d["balloon_pollution"]
            + model.x["gondola"] * d["gondola_pollution"]
            for _ in [0]
        ),
        sense=pyo.minimize,
    )

    # 4. Constraints

    # Total visitors transported must be at least the requirement.
    def visitors_rule(m):
        return (
            m.x["balloon"] * d["balloon_capacity"]
            + m.x["gondola"] * d["gondola_capacity"]
            >= d["min_visitors"]
        )

    model.visitors = pyo.Constraint(rule=visitors_rule)

    # At most max_balloon_rides hot-air balloon rides.
    def max_balloon_rule(m):
        return m.x["balloon"] <= d["max_balloon_rides"]

    model.max_balloon = pyo.Constraint(rule=max_balloon_rule)

    return model


